/* Offline product prototype. All interactions operate on synthetic fixtures.
 * localStorage is namespaced and bounded; nothing reads or writes game saves.
 * V1/V2 compatibility screens describe a contract, not a completed migration.
 */
"use strict";
(() => {
  const D = window.AZS_DEMO;
  const KEY = "azerothstats-v2-prototype-20261030";
  const THEMES = ["chroniques", "warcraft", "atelier", "essentiel", "grimoire"];
  const METRICS = {runs:"Parties suivies",wins:"Victoires",time:"Temps de jeu",kills:"Victimes",gold:"Or",damage:"Dégâts",bosses:"Boss observés",levels:"Niveaux stockés"};
  const METRIC_GLYPHS = {runs:2,wins:3,time:4,kills:5,gold:15,damage:2,bosses:5,levels:9};
  const E = id => document.getElementById(id);
  const esc = value => String(value ?? "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
  const n = value => value == null ? "Indisponible" : new Intl.NumberFormat("fr-FR", {maximumFractionDigits:0}).format(value);
  const short = value => value == null ? "Indisponible" : value >= 1e9 ? (value/1e9).toLocaleString("fr-FR",{maximumFractionDigits:2})+" Md" : value >= 1e6 ? (value/1e6).toLocaleString("fr-FR",{maximumFractionDigits:2})+" M" : value >= 1e4 ? (value/1e3).toLocaleString("fr-FR",{maximumFractionDigits:1})+" k" : n(value);
  const clock = t => {const s=Math.floor(t || 0);return s>=3600?`${Math.floor(s/3600)} h ${String(Math.floor(s/60)%60).padStart(2,"0")} min`:`${String(Math.floor(s/60)).padStart(2,"0")}:${String(s%60).padStart(2,"0")}`;};
  const icon = (i, cls="") => `<img class="${cls}" src="assets/ChronicleGlyph${String(i).padStart(2,"0")}.png" alt="">`;
  const photo = (r, cls="zone-thumb") => `<img class="${cls}" src="assets/RunZone-${esc(r.zone)}.png" alt="${esc(D.zones[r.zone])}">`;
  const tag = (s,c="") => `<span class="tag ${c}">${esc(s)}</span>`;
  const btn = (label,action,extra="",cls="") => `<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
  const sum = (runs,key) => runs.reduce((a,r)=>a+(r[key]||0),0);
  const stored = (() => {try {const raw=localStorage.getItem(KEY);return raw&&raw.length<70000?JSON.parse(raw):{};} catch {return {};}})();
  const S = {
    page:"home",tab:"",selected:"d12",compareA:"d11",compareB:"d06",compareMetric:"damage",
    classFilter:"all",difficulty:"all",mode:"all",result:"all",query:"",pageIndex:1,
    chartMetric:"kills",favoriteCategory:"runs",progressTab:"records",buildTab:"spells",combatTab:"damage",edit:false,
    theme:THEMES.includes(stored.theme)?stored.theme:"chroniques",density:stored.density==="compact"?"compact":"comfort",
    favorites:Array.isArray(stored.favorites)?stored.favorites.filter(x=>typeof x==="string"&&x.length<80).slice(0,100):["run:d11","run:d09","spell:tourbillon","item:justice"],
    deleted:Array.isArray(stored.deleted)?stored.deleted.filter(x=>D.runs.some(r=>r.id===x)).slice(0,12):[],
    resetMetrics:Array.isArray(stored.resetMetrics)?stored.resetMetrics.filter(x=>typeof x==="string"&&["duration","damage","gold","kills","level","healing","taken"].some(k=>x===k||["all",...D.classes].some(c=>x===c+":"+k))).slice(0,35):[],
    hidden:Array.isArray(stored.hidden)?stored.hidden.filter(x=>typeof x==="string"&&x.length<100).slice(0,100):[],
    notes:stored.notes&&typeof stored.notes==="object"&&!Array.isArray(stored.notes)?Object.fromEntries(Object.entries(stored.notes).filter(([k,v])=>D.runs.some(r=>r.id===k)&&typeof v==="string").map(([k,v])=>[k,v.slice(0,240)])): {},
    hud:{width:960,height:48,font:12,icons:true,labels:true,visible:true,blocks:[{metric:"runs",scope:"all"},{metric:"wins",scope:"all"},{metric:"time",scope:"all"},{metric:"kills",scope:"all"}]},
    overlay:null,hudDraft:null,toastTimer:null
  };
  if(stored.hud&&Array.isArray(stored.hud.blocks)) {
    const blocks=stored.hud.blocks.filter(b=>b&&Object.hasOwn(METRICS,b.metric)&&["all","class","run"].includes(b.scope)).slice(0,8);
    if(blocks.length) S.hud.blocks=blocks;
    for(const k of ["width","height","font"]) if(Number.isFinite(stored.hud[k])) S.hud[k]=Math.max(k==="width"?480:k==="height"?38:10,Math.min(k==="width"?1260:k==="height"?76:16,stored.hud[k]));
    for(const k of ["icons","labels","visible"]) if(typeof stored.hud[k]==="boolean") S.hud[k]=stored.hud[k];
  }
  const persist = () => {try{localStorage.setItem(KEY, JSON.stringify({theme:S.theme,density:S.density,favorites:S.favorites,deleted:S.deleted,resetMetrics:S.resetMetrics,hidden:S.hidden,notes:S.notes,hud:S.hud}));}catch{toast("Le navigateur ne permet pas de conserver les préférences de la maquette.");}};
  const run = () => D.runs.find(r=>r.id===S.selected&&!S.deleted.includes(r.id)) || D.runs.find(r=>!S.deleted.includes(r.id)) || D.runs[0];
  const available = () => D.runs.filter(r=>!S.deleted.includes(r.id));
  const favorite = key => S.favorites.includes(key);
  const heart = key => `<button class="heart ${favorite(key)?"saved":""}" data-action="favorite" data-key="${esc(key)}" aria-label="${favorite(key)?"Retirer des favoris":"Ajouter aux favoris"}" aria-pressed="${favorite(key)}">${favorite(key)?"♥":"♡"}</button>`;
  const result = r => ({victory:"Victoire",defeat:"Défaite",left:"Abandon",live:"En cours"}[r.result]);
  const resultClass = r => r.result==="victory"?"result-win":r.result==="defeat"?"result-loss":r.result==="left"?"result-left":"";
  const diff = r => r.heroic?`Heroic ${["","I","II","III","IV","V"][r.heroic]}`:"Normal";
  const cohort = () => D.runs.filter(r=>S.classFilter==="all"||r.class===S.classFilter);
  const cohortLabel = () => S.classFilter==="all"?"Toutes les classes":S.classFilter;
  const filtered = () => available().filter(r=>(S.classFilter==="all"||r.class===S.classFilter)&&(S.difficulty==="all"||String(r.heroic)===S.difficulty)&&(S.mode==="all"||r.mode===S.mode)&&(S.result==="all"||r.result===S.result)&&`${D.zones[r.zone]} ${r.class} ${diff(r)} ${r.mode} ${r.date}`.toLocaleLowerCase().includes(S.query.toLocaleLowerCase()));
  function spellsFor(r) {
    const names={Mage:["Boule de feu","Blizzard","Éclair de givre","Nova de givre","Enflammer","Attaque de baguette"],Voleur:["Attaque sournoise","Attaque pernicieuse","Déluge de lames","Frappe fantomatique","Poison mortel","Mêlée"],Chasseur:["Visée","Salve","Tir des arcanes","Flèches multiples","Morsure du serpent","Tir automatique"]}[r.class];
    return names?D.spells.map((s,i)=>({...s,name:names[i],key:r.class.toLowerCase()+"-"+i})):D.spells;
  }
  function partyFor(r) {
    const factor=r.damage/D.runs[0].damage;
    const peers=D.party.filter(p=>!p.self).slice(0,Math.max(0,r.players-1));
    return [...peers,{...D.party.find(p=>p.self),class:r.class,top:spellsFor(r)[0].name}].map(p=>({...p,damage:Math.round(p.damage*factor),dps:Math.round(p.damage*factor/r.duration)})).sort((a,b)=>b.damage-a.damage);
  }
  function encountersFor(r) {
    const names={elwynn:["Lardeur","Princesse","Lardeur enragé","Hogger — final"],naxx:["Anub’Rekhan","Grande veuve Faerlina","Maexxna","Kel’Thuzad"],ungoro:["Ravasaur matriarche","Roi Mosh","Diablosaure","Reine du cratère"],sm:["Interrogateur Vishas","Maître-chien Loksey","Hérode","Grande inquisitrice Blanchetête"],feralas:["Lethtendris","Zevrim Sabot-de-ronce","Alzzin le Modeleur","Prince Tortheldrin"],av:["Capitaine Galvangar","Drek’Thar","Vanndar Foudrepique","Géant des montagnes"]}[r.zone];
    return D.encounters.map((b,i)=>({...b,name:names?names[i]:b.name,damage:Math.round(b.damage*r.damage/D.runs[0].damage)}));
  }
  function equipmentFor(r) {
    const names={Mage:["Diadème de givrefeu","Épaulières de givrefeu","Robe de givrefeu"],Voleur:["Couvre-chef de Tueur de la nuit","Spallières de Tueur de la nuit","Plastron de Tueur de la nuit"],Chasseur:["Heaume de traqueur de dragon","Épaulières de traqueur de dragon","Cuirasse de traqueur de dragon"]}[r.class];
    return D.equipment.map((i,index)=>({...i,name:names&&index<3?names[index]:i.name}));
  }
  function journalFor(r) {
    const names=spellsFor(r);
    return D.journal.filter(j=>j.t<=r.duration).map(j=>({...j,title:j.title.replaceAll("Tourbillon",names[0].name).replaceAll("Heurt de bouclier",names[1].name)}));
  }
  const nav = [
    ["home","Vue d’ensemble",13],["runs","Mes parties",6],["analyze","Analyser une partie",2],
    ["progress","Ma progression",8],["favorites","Mes favoris",10],["nemesis","Némésis",5]
  ];
  function select(options,value,id,extra="") {return `<select id="${id}" ${extra}>${options.map(([v,l])=>`<option value="${esc(v)}"${String(v)===String(value)?" selected":""}>${esc(l)}</option>`).join("")}</select>`;}
  function heading(eyebrow,title,description,actions="") {return `<div class="page-heading"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:""}</div>`;}
  function scope() {return `<div class="scope-select">${select([["all","Toutes les classes"],...D.classes.map(c=>[c,c])],S.classFilter,"class-filter","aria-label=\"Filtrer par classe\"")}</div>`;}
  function runPicker(id="run-picker",value=S.selected) {return select(available().map(r=>[r.id,`${D.zones[r.zone]} · ${r.class} · ${r.date}${r.result==="live"?" · EN COURS":""}`]),value,id,'aria-label="Partie sélectionnée"');}
  function tabs(items,active,action="tab") {return `<div class="tabs" role="tablist">${items.map(([id,label])=>`<button class="tab ${active===id?"active":""}" role="tab" aria-selected="${active===id}" data-action="${action}" data-tab="${id}">${esc(label)}</button>`).join("")}</div>`;}
  function stat(label,value,detail,glyph=13,good=false,resetKey="") {return `<div class="stat">${icon(glyph,"stat-icon")}<div class="stat-label">${esc(label)}</div><strong class="${good?"good":""}">${esc(value)}</strong><small>${esc(detail)}</small>${S.edit&&resetKey?btn("Réinitialiser","reset-record",`data-key="${resetKey}"`,"small stat-reset"):""}</div>`;}
  function section(title,action="",body="",sub="") {return `<div class="section-heading"><h2>${title}</h2>${action||`<small>${sub}</small>`}</div>${body}`;}
  function line(label,value) {return `<div class="metric-line"><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`;}
  function qualityNote(text="Les nombres de cette maquette sont fictifs. Les libellés de source illustrent la future interface.") {return `<div class="quality-note"><span class="online"></span>${esc(text)} <button class="text-link" data-action="quality">En savoir plus</button></div>`;}
  function editAction() {return btn(S.edit?"Terminer l’édition":"Modifier cette vue","edit", "", S.edit?"primary":"ghost");}
  function editHint() {return S.edit?`<div class="edit-hint">Mode édition · choisissez une ligne pour masquer son affichage ou réinitialiser uniquement son enregistrement. ${btn("Tout réafficher","restore-hidden","","small")}</div>`:"";}
  function row(r) {return `<div class="run-row" data-action="open-run" data-id="${r.id}" tabindex="0" role="button" aria-label="Ouvrir ${esc(D.zones[r.zone])}, ${esc(r.date)}">${photo(r)}<div class="run-main"><div class="run-name">${esc(D.zones[r.zone])} ${r.result==="live"?tag("PARTIE EN COURS","gold"):""}</div><small>${esc(r.class)} · ${esc(diff(r))} · ${r.mode==="Coop"?`Coop · ${r.players} joueurs observés`:"Solo"}</small><small>${esc(r.date)}${r.affixes.length?` · ${r.affixes.map(esc).join(", ")}`:""}</small></div><div class="run-result"><span class="${resultClass(r)}">${result(r)}</span><small>${clock(r.duration)}</small></div>${heart("run:"+r.id)}${S.edit?btn("…","entry-menu",`data-kind="run" data-id="${r.id}"`,"small"):""}</div>`;}
  function empty(title,message,action="") {return `<div class="empty">${icon(9)}<h2>${esc(title)}</h2><p>${esc(message)}</p>${action}</div>`;}
  function hero(r,compact=false) {return `<div class="hero-run">${photo(r,"hero-photo")}<div class="hero-text"><div class="eyebrow">${r.result==="live"?"Votre partie en cours":"Carnet de partie"}</div><h2>${esc(D.zones[r.zone])}</h2><div class="hero-meta"><span>${esc(r.class)}</span>${tag(diff(r),"gold")}${tag(r.mode==="Coop"?`Coop · ${r.players} joueurs observés`:"Solo")}${r.affixes.map(a=>tag(a)).join("")}<span>${esc(r.date)}</span></div>${compact?"":`<p>${r.coverage<100?"Le suivi a commencé après le début de la partie. Les périodes manquantes restent signalées.":"Retrouvez le build, les combats et les moments marquants de cette aventure."}</p>`}</div><div class="hero-status"><span class="${resultClass(r)}">${result(r)} · ${clock(r.duration)}</span>${heart("run:"+r.id)}${S.page==="home"?btn("Reprendre l’analyse →","open-run",`data-id="${r.id}"`,"primary"):""}</div></div>`;}
  function chart(r,metric=S.chartMetric,compare=null) {
    const field={kills:"kills",damage:"damage",gold:"gold",level:"level",dps:"damage"}[metric]||"kills";
    const label={kills:"Victimes cumulées",damage:"Dégâts cumulés",gold:"Or possédé",level:"Niveau",dps:"DPS moyen sur l’intervalle"}[metric]||"Victimes cumulées";
    const points=(obj)=>{const arr=[];let previous=0;for(let t=0;t<obj.duration;t+=15){const value=obj[field]*Math.pow(t/obj.duration,1.45);arr.push([t,metric==="dps"?(t?Math.max(0,(value-previous)/15):0):value]);previous=value;}arr.push([obj.duration,metric==="dps"?obj.damage/obj.duration*1.42:obj[field]]);return arr;};
    const a=points(r),b=compare?points(compare):[],maxT=Math.max(r.duration,compare?.duration||0),maxY=Math.max(...a.map(v=>v[1]),...b.map(v=>v[1]),1)*1.08;
    const path=arr=>arr.map(([x,y],i)=>`${i?"L":"M"}${(58+x/maxT*570).toFixed(1)},${(188-y/maxY*148).toFixed(1)}`).join(" ");
    return `<div class="panel"><div class="section-heading"><h2>${label}</h2><div class="segmented" aria-label="Mesure du graphique">${[["kills","Victimes"],["damage","Dégâts"],["gold","Or"],["level","Niveau"],["dps","DPS"]].map(([key,name])=>`<button class="${metric===key?"active":""}" data-action="chart" data-key="${key}">${name}</button>`).join("")}</div></div><svg class="chart" viewBox="0 0 660 225" role="img" aria-label="${label}, démonstration synthétique. Temps écoulé en minutes sur l’axe horizontal.">${[0,1,2,3].map(i=>`<line class="gridline" x1="58" y1="${40+i*49.3}" x2="628" y2="${40+i*49.3}"/><text x="50" y="${43+i*49.3}" text-anchor="end">${esc(short(maxY*(1-i/3)))}</text><text x="${58+i*190}" y="206" text-anchor="middle">${clock(maxT*i/3)}</text>`).join("")}<text x="58" y="18">${esc(metric==="dps"?"Dégâts / seconde":metric==="gold"?"Or possédé":metric==="level"?"Niveau":metric==="damage"?"Dégâts":"Victimes")}</text><text x="628" y="223" text-anchor="end">Temps écoulé (min:s)</text><path class="line" d="${path(a)}"/>${compare?`<path class="line secondary-line" d="${path(b)}"/>`:""}${a.filter((_,i)=>i%8===0).map(([t,v])=>`<circle cx="${58+t/maxT*570}" cy="${188-v/maxY*148}" r="3"><title>${clock(t)} · ${label} : ${n(v)} · données fictives</title></circle>`).join("")}</svg><div class="chart-legend"><span><i class="legend-mark"></i>${esc(D.zones[r.zone])} · ${r.date}</span>${compare?`<span>┄ ${esc(D.zones[compare.zone])} · ${compare.date}</span>`:""}</div><p class="note">Courbe synthétique de démonstration · points espacés de 15 secondes. ${metric==="dps"?"Moyenne d’intervalle, pas DPS instantané.":metric==="gold"?"Solde observé, pas revenu brut ni gain attribué à une carte.":"Les interruptions et données manquantes seront affichées dans l’addon."}</p></div>`;
  }
  function home() {
    const list=cohort(),wins=list.filter(r=>r.result==="victory").length,live=D.runs[0];
    return heading("Votre aventure","Vue d’ensemble","L’essentiel maintenant. Les détails quand vous en avez besoin.",scope())+hero(live)+
      `<div class="stats-grid">${stat("Parties suivies",list.length,"Toutes périodes · scénario fictif",2)}${stat("Victoires",wins,`${Math.round(wins/list.length*100)} % des parties suivies`,3,true)}${stat("Temps de jeu",clock(sum(list,"duration")),cohortLabel(),4)}${stat("Victimes",short(sum(list,"kills")),cohortLabel(),5)}</div>`+
      `<div class="two-columns"><div>${section("Vos dernières parties",btn("Tout l’historique →","go","data-route=\"runs\"","small ghost"),`<div class="run-list">${available().filter(r=>r.result!=="live"&&(S.classFilter==="all"||r.class===S.classFilter)).slice(0,3).map(row).join("")}</div>`)}<div class="spacer"></div>${chart(live)}</div><div>${section("À retenir","",`<div class="panel"><div class="insight">${icon(8)}<div><h3>Un nouveau palier franchi</h3><p>Forêt d’Elwynn · victoire en Heroic III dans ce scénario.</p><button class="text-link" data-action="open-run" data-id="d11">Revoir cette partie →</button></div></div><div class="insight">${icon(2)}<div><h3>Comprendre votre puissance</h3><p>Attributs complets, équipement et changements observés regroupés dans Build.</p><button class="text-link" data-action="analyze-tab" data-tab="build">Explorer mon build →</button></div></div><div class="insight">${icon(10)}<div><h3>Gardez vos aventures marquantes</h3><p>Un cœur suffit pour retrouver une partie, un sort ou un équipement.</p><button class="text-link" data-action="go" data-route="favorites">Voir mes favoris →</button></div></div></div>`)}<div class="spacer"></div>${section("Votre prochain objectif","",`<div class="panel"><div class="eyebrow">Objectif personnel · démonstration</div><h3>Trois victoires en Heroic III</h3><div class="progress-track"><span style="width:33%"></span></div><p class="note">1 / 3 · basé sur les parties retenues, pas sur les déblocages officiels.</p>${btn("Mes objectifs →","progress-tab","data-tab=\"goals\"","small ghost")}</div>`)}</div></div>`+qualityNote();
  }
  function runs() {
    const list=filtered(),per=5,pages=Math.max(1,Math.ceil(list.length/per));S.pageIndex=Math.min(S.pageIndex,pages);
    const filters=`<div class="filters"><input id="history-search" type="search" placeholder="Rechercher une zone, une classe, une date…" aria-label="Rechercher dans l’historique" value="${esc(S.query)}">${select([["all","Toutes difficultés"],...[0,1,2,3,4,5].map(v=>[v,v?`Heroic ${["","I","II","III","IV","V"][v]}`:"Normal"])],S.difficulty,"difficulty-filter","aria-label=\"Difficulté\"")}${select([["all","Solo et coop"],["Solo","Solo"],["Coop","Coop"]],S.mode,"mode-filter","aria-label=\"Mode de jeu\"")}${select([["all","Tous les résultats"],["victory","Victoire"],["defeat","Défaite"],["live","En cours"],["left","Abandon"]],S.result,"result-filter","aria-label=\"Résultat\"")}<button class="reset" data-action="reset-filters">Réinitialiser les filtres</button></div>`;
    return heading("Votre carnet","Mes parties","Retrouvez un contexte, un build et les moments qui ont compté.",scope()+btn("Comparer deux parties","go","data-route=\"compare\"","primary"))+filters+
      `<div class="cohort-strip"><span><strong>${list.length} parties retenues</strong> correspondent aux filtres</span><span>${list.filter(r=>r.result==="victory").length} victoires · ${clock(sum(list,"duration"))} observées</span>${editAction()}</div>${editHint()}`+
      (list.length?`<div class="run-list">${list.slice((S.pageIndex-1)*per,S.pageIndex*per).map(row).join("")}</div>`:empty("Aucune partie ne correspond","Essayez une autre classe ou retirez un filtre. Votre historique n’a pas été modifié.",btn("Effacer les filtres","reset-filters")))+
      `<div class="pagination"><span>${list.length} résultat${list.length>1?"s":""} · détails conservés</span><div>${btn("←","page",`data-delta="-1" ${S.pageIndex===1?"disabled":""}`,"small")}<span>Page ${S.pageIndex} / ${pages}</span>${btn("→","page",`data-delta="1" ${S.pageIndex===pages?"disabled":""}`,"small")}</div></div>`+qualityNote("Une partie favorite est protégée de la purge automatique. Les totaux peuvent couvrir davantage de parties que l’historique retenu.");
  }
  const analysisTabs=[["overview","Bilan"],["combat","Combat"],["build","Build"],["encounters","Rencontres"],["coop","Coop"],["endless","Endless"]];
  function analysis() {
    const r=run(),sub=S.tab||"overview";
    return heading(S.page==="run"?"Mes parties / Partie sélectionnée":"Comprendre votre partie",S.page==="run"?"Bilan de partie":"Analyser une partie","Une seule partie sélectionnée pour tous les détails.",`<div class="scope-select">${runPicker()}</div>`)+hero(r,true)+tabs(analysisTabs.filter(t=>t[0]!=="endless"||r.hasEndless),sub)+
      (sub==="overview"?runOverview(r):sub==="combat"?combat(r):sub==="build"?build(r):sub==="encounters"?encounters(r):sub==="endless"?endless(r):coop(r));
  }
  function endless(r) {
    return `<div class="stats-grid">${stat("Victoire initiale",clock(r.victoryAt),"Jalon du scénario fictif",3,true)}${stat("Continuation observée",clock(r.duration-r.victoryAt),"Durée après le jalon",4)}${stat("Parties comptées",1,"Une identité, un seul décompte",2)}${stat("Cycles exacts","Non établis","Aucun sens de endl inventé",9)}</div><div class="panel"><h2>Une victoire, puis l’aventure continue</h2><p class="note">Le résultat de victoire initial est conservé. Les nouveaux compteurs communs enrichissent cette même partie, sans compter une seconde victoire ou une deuxième partie.</p></div><div class="callout">Contrat natif à confirmer pendant le développement<small>Le champ endl existe, mais sa sémantique ne sera pas devinée. Cette vue illustre la séparation des deux moments avec des données fictives.</small></div>`;
  }
  function runOverview(r) {
    return `<div class="stats-grid">${stat("Durée de partie",clock(r.duration),r.result==="live"?"Dernier échantillon":"Résumé officiel · démo",4)}${stat("Niveau",r.level,"Dernier niveau observé",7)}${stat("Victimes",short(r.kills),"Compteur de partie",5)}${stat("Dégâts infligés",short(r.damage),"Compteur de partie",2)}</div><div class="two-columns"><div>${chart(r)}<div class="spacer"></div>${section("Les moments marquants","",`<div class="panel"><div class="timeline">${journalFor(r).slice(0,3).map(j=>`<div class="timeline-item"><span class="timeline-time">${clock(j.t)}</span><p>${esc(j.title)}</p><small>${esc(j.detail)}</small></div>`).join("")}</div>${btn("Ouvrir le journal du build →","build-tab","data-tab=\"journal\"","small ghost")}</div>`)}</div><div>${section("Le contexte","",`<div class="panel">${line("Mode",r.mode==="Coop"?`Coop · ${r.players} joueurs observés`:"Solo")}${line("Difficulté",diff(r))}${line("Affixes",r.affixes.join(", ")||"Aucun dans le scénario")}${line("Or",n(r.gold))}${line("Coffres ouverts",r.chests==null?"Disponible à la fin":r.chests)}${line("Suivi",r.coverage<100?"Partiel — début manquant":"Depuis le début")}</div>`)}<div class="spacer"></div>${section("Votre note","",`<div class="panel"><label for="run-note" class="note">Un souvenir, une idée de build, un point à revoir.</label><textarea id="run-note" maxlength="240" rows="3" placeholder="Ajouter une note privée à cette partie…">${esc(S.notes[r.id]||"")}</textarea><p class="note">Dans cette maquette : enregistré uniquement dans ce navigateur.</p></div>`)}<div class="callout">${r.coverage<100?"Une partie de l’aventure n’a pas été observée.":"Ce bilan conserve le contexte de la partie."}<small>Les affixes et rencontres affichés sont une démonstration des nouvelles vues, pas une capture du jeu.</small></div>${btn("Comparer cette partie →","compare-from",`data-id="${r.id}"`,"ghost")}</div></div>`;
  }
  function combat(r) {
    const modes=[["damage","Dégâts infligés"],["healing","Soins effectifs"],["taken","Dégâts reçus"],["effects","Buffs & debuffs"]],mode=S.combatTab;
    if(mode==="effects")return tabs(modes,mode,"combat-tab")+`<div class="callout">Effets observés pendant les rencontres<small>Présence échantillonnée, aucun uptime exact ni liste exhaustive des effets ennemis.</small></div><div class="table-wrap"><table class="detail-table"><thead><tr><th>Effet</th><th>Cible / contexte</th><th class="num">Cumul maximum observé</th><th>Couverture</th></tr></thead><tbody><tr><td>Pourfendre</td><td>Rencontres de boss</td><td class="num">3</td><td>${tag("Échantillonné")}</td></tr><tr><td>Cri démoralisant</td><td>Cibles documentées</td><td class="num">1</td><td>${tag("Partiel")}</td></tr><tr><td>Berserker</td><td>Personnage</td><td class="num">Indisponible</td><td>${tag("Présence observée")}</td></tr></tbody></table></div>`+qualityNote();
    const total=r[mode],sources=mode==="taken"?[{name:"Attaques de mêlée",share:51,glyph:2},{name:"Sorts des créatures",share:31,glyph:12},{name:"Dégâts périodiques",share:18,glyph:5}]:mode==="healing"?[{name:"Vol de vie",share:67,glyph:10},{name:"Régénération",share:24,glyph:3},{name:"Soins sur victime",share:9,glyph:8}]:spellsFor(r);
    return tabs(modes,mode,"combat-tab")+`<div class="cohort-strip"><span>${modes.find(m=>m[0]===mode)[1]} · <strong>${esc(D.zones[r.zone])}</strong></span>${editAction()}</div>${editHint()}<div class="stats-grid">${stat("Total",short(total),"Dernier compteur disponible",2)}${stat("Par seconde",short(total/r.duration),"Moyenne sur toute la partie",12)}${stat("Temps serveur",clock(r.duration),"Horloge de référence",4)}${stat("Sources observées",sources.length,"Aucune source manquante convertie en zéro",9)}</div><div class="panel"><div class="table-head"><span>Source</span><span>Part</span><span>Total</span><span></span></div>${sources.filter(s=>!S.hidden.includes("source:"+s.name)).map(s=>`<div class="meter-row">${icon(s.glyph)}<div class="meter-label">${esc(s.name)}<small>${s.proc?"Déclenchement automatique · ":""}${short(total*s.share/100/r.duration)} /s sur la partie</small></div><span class="share">${s.share.toLocaleString("fr-FR")} %</span><span class="value">${short(total*s.share/100)}</span>${S.edit?btn("…","entry-menu",`data-kind="source" data-id="${esc(s.name)}"`,"small"):heart("spell:"+(s.key||s.name))}<div class="meter-track"><div class="meter-fill" style="--width:${s.share}%"></div></div></div>`).join("")}</div>`+qualityNote("Part de contribution, rangs et taux ont chacun leur colonne. Une moyenne de partie ne mesure pas un pic instantané.");
  }
  function build(r) {
    const options=[["spells","Sorts"],["attributes","Caractéristiques"],["equipment","Équipement"],["journal","Journal"],["summons","Invocations"]],t=S.buildTab;
    let body="";
    if(t==="spells")body=`<div class="section-heading"><h2>Votre build observé</h2>${editAction()}</div>${editHint()}<div class="table-wrap"><table class="detail-table"><thead><tr><th>Sort</th><th class="num">Dernier rang</th><th class="num">Gains de rang observés</th><th>Favori</th></tr></thead><tbody>${spellsFor(r).filter(s=>!S.hidden.includes("spell:"+s.key)).map(s=>`<tr><td>${icon(s.glyph)}${esc(s.name)}${s.proc?tag("Proc"):""}</td><td class="num">${s.rank}</td><td class="num">${s.changes}</td><td>${S.edit?btn("…","entry-menu",`data-kind="spell" data-id="${s.key}"`,"small"):heart("spell:"+s.key)}</td></tr>`).join("")}</tbody></table></div><p class="note">Rang et variation observés ≠ nombre de clics ou de lancements.</p>`;
    else if(t==="attributes")body=`<div class="cohort-strip"><span><strong>Votre puissance, expliquée</strong> · total reçu du client et contribution de l’équipement</span>${select([["all","Toutes les caractéristiques"],["essential","Essentielles"],["advanced","Avancées V2"],["gear","Contribution équipement"]],S.attributeGroup||"all","attribute-group",'aria-label="Groupe de caractéristiques"')}</div><div class="table-wrap"><table class="detail-table"><thead><tr><th>Caractéristique</th><th class="num">Total observé</th><th class="num">Part équipement déclarée</th><th>Lecture</th></tr></thead><tbody>${D.attributes.filter(a=>!S.attributeGroup||S.attributeGroup==="all"||(S.attributeGroup==="gear"?a[2]!=null:S.attributeGroup==="advanced"?["echo","pick","big","exe","cc","doth","thn","liv","bp","dots","dotd","shd","auto","pet"].includes(a[3]):!["echo","pick","big","exe","cc","doth","thn","liv","bp","dots","dotd","shd","auto","pet"].includes(a[3]))).map(([label,total,gear,key])=>`<tr><td>${label}<small>${["echo","pick","big","exe","cc","doth","thn","liv","bp","dots","dotd","shd","auto","pet"].includes(key)?"Analyse enrichie V2":"Déjà présente en V1"}</small></td><td class="num">${total}</td><td class="num">${gear||"Non exposée"}</td><td>${btn("?","attribute",`data-key="${key}"`,"small ghost")}</td></tr>`).join("")}</tbody></table></div><p class="note">Les contributions d’équipement ne permettent pas d’attribuer le reste à une carte. Les valeurs affichées sont des exemples fictifs.</p>`;
    else if(t==="equipment")body=`<div class="section-heading"><h2>Équipement conservé avec la partie</h2>${tag("Descriptions capturées")}</div><div class="equipment-grid">${equipmentFor(r).map(i=>`<button class="item" data-action="item" data-key="${i.key}">${icon(i.glyph)}<span><strong>${esc(i.name)}</strong><small>${esc(i.slot)}</small></span><span class="mini-tag">Détails →</span></button>`).join("")}</div><div class="callout">La description appartient à cette observation.<small>Étoiles et bonus de set : conservés comme texte si le tooltip natif les expose. Aucun rang d’étoile ou bonus activé n’est reconstruit à partir du seul ID d’objet.</small></div>`;
    else if(t==="journal")body=`<div class="section-heading"><h2>L’évolution de votre build</h2>${select([["all","Tous les changements"],["spell","Sorts"],["stats","Caractéristiques"],["gear","Équipement"]],S.journalKind||"all","journal-kind")}</div><div class="callout">Un journal de changements, pas une liste de cartes cliquées.<small>Plusieurs bonus peuvent évoluer ensemble. Leur simultanéité ne prouve pas une cause.</small></div><div class="panel"><div class="timeline">${journalFor(r).filter(j=>!S.journalKind||S.journalKind==="all"||j.kind===S.journalKind).map(j=>`<div class="timeline-item"><span class="timeline-time">${clock(j.t)}</span><p>${esc(j.title)}</p><small>${esc(j.detail)}</small></div>`).join("")}</div></div>`;
    else body=`<div class="stats-grid">${stat("Invocations simultanées",3,"Maximum observé · scénario Chasseur",7)}${stat("Familles observées",2,"Clés natives présentes",9)}${stat("Totems", "Indisponible","Pas de donnée dans ce scénario",11)}${stat("Lancements exacts","Non exposés","Une présence ne compte pas les casts",12)}</div><div class="table-wrap"><table class="detail-table"><thead><tr><th>Invocation</th><th>Nature</th><th class="num">Maximum simultané</th><th>Fenêtres observées</th></tr></thead><tbody><tr><td>Familier du chasseur</td><td>Permanent</td><td class="num">1</td><td>02:15 → 15:34 · partiel</td></tr><tr><td>Loups spirituels</td><td>Temporaire</td><td class="num">2</td><td>07:12 → 07:42</td></tr></tbody></table></div><div class="callout">Scénario de capacité séparé<small>Ces exemples d’invocations illustrent les nouvelles vues. Ils ne sont pas attribués au Guerrier sélectionné et ne permettent pas de calculer leurs dégâts.</small></div>`;
    return tabs(options,t,"build-tab")+body+qualityNote();
  }
  function encounters(r) {return `<div class="section-heading"><div><h2>Les rencontres de la partie</h2><p class="note">Une chronologie lisible, du premier boss au dernier relevé.</p></div>${tag("NOUVEAU V2","gold")}</div><div class="run-list">${encountersFor(r).map(b=>`<div class="encounter-row" role="button" tabindex="0" data-action="encounter" data-id="${b.id}">${icon(b.glyph)}<div><strong>${esc(b.name)}</strong><small>Apparition observée à ${clock(b.t)} · ${b.state}</small></div><span>${b.end?clock(b.end-b.t):"En cours"}<small>${short(b.damage)} dégâts observés</small></span></div>`).join("")}</div><div class="callout">Un boss qui disparaît n’est pas automatiquement un boss tué.<small>Rencontres et compteurs présentés ici : scénario fictif de la zone sélectionnée. Dans l’addon, les rencontres ne seront attachées à une partie que si le suivi natif le permet. Les boss simultanés peuvent partager un compteur.</small></div>`+qualityNote();}
  function coop(r) {
    if(r.mode!=="Coop")return empty("Cette partie a été jouée en solo","Les données de groupe restent liées à leur partie. Sélectionnez un scénario coop pour parcourir cette vue.",btn("Voir la partie coop en cours","open-run","data-id=\"d12\" data-sub=\"coop\"","primary"));
    const party=partyFor(r),total=sum(party,"damage");
    return `<div class="stats-grid">${stat("Joueurs observés",party.length,"Un relevé de groupe commun",9)}${stat("Dégâts du groupe",short(total),"Même instant d’observation",2)}${stat("Votre contribution",(r.damage/total*100).toLocaleString("fr-FR",{maximumFractionDigits:1})+" %","Sur ce relevé uniquement",13)}${stat("Votre mise à terre",1,"Une transition observée",16)}</div><div class="section-heading"><h2>Le groupe, au même instant</h2><div class="segmented"><button class="active" data-action="toast" data-message="Le classement est fondé uniquement sur le relevé de dégâts commun.">Dégâts</button><button data-action="coop-support">Soutien observé</button></div></div><div class="table-wrap"><table class="detail-table"><thead><tr><th>Joueur</th><th class="num">Dégâts</th><th class="num">Part</th><th>Meilleure source</th><th>Détails</th></tr></thead><tbody>${party.map(p=>`<tr class="coop-row ${p.self?"self":""}"><td><div class="player-name">${icon(p.glyph)}${p.name} ${p.self?tag("Vous","gold"):""}</div><small>${p.class}</small></td><td class="num">${short(p.damage)}</td><td class="num">${(p.damage/total*100).toLocaleString("fr-FR",{maximumFractionDigits:1})} %</td><td>${p.top}</td><td>${btn("Voir →","player",`data-key="${p.name}"`,"small ghost")}</td></tr>`).join("")}</tbody></table></div><div class="spacer"></div>${section("Moments de soutien","",`<div class="panel"><div class="timeline"><div class="timeline-item"><span class="timeline-time">08:12</span><p>Maiden est à terre</p><small>État local reçu du client ; la partie n’est pas terminée.</small></div><div class="timeline-item"><span class="timeline-time">08:18</span><p>Lockpin commence à vous relever</p><small>Progression de réanimation observée.</small></div><div class="timeline-item"><span class="timeline-time">08:24</span><p>Maiden reprend le combat</p><small>Transition cohérente dans le scénario ; à valider avec les paquets natifs.</small></div></div></div>`)}<p class="note">Le relevé de dégâts est disponible dans la V1. Le soutien observé est une extension V2. Pas de soins ou d’équipement alliés inventés.</p>`;
  }
  function compare() {
    const a=D.runs.find(r=>r.id===S.compareA)||D.runs[1],b=D.runs.find(r=>r.id===S.compareB)||D.runs[6],same=a.class===b.class&&a.zone===b.zone&&a.heroic===b.heroic&&a.mode===b.mode&&a.players===b.players&&a.affixes.join()===b.affixes.join();
    return heading("Mes parties / Comparer","Deux aventures, un regard plus précis","Le contexte avant les chiffres. Aucun score global de « meilleur joueur ».",btn("← Historique","go","data-route=\"runs\"","ghost"))+
      `<div class="compare-slots">${[[a,"compare-a","PARTIE A"],[b,"compare-b","PARTIE B"]].map(([r,id,label])=>`<div class="compare-slot">${photo(r)}<div><div class="eyebrow">${label}</div>${runPicker(id,r.id)}<small>${r.class} · ${diff(r)} · ${r.mode} · ${clock(r.duration)}</small></div></div>`).join("")}</div><div class="callout ${same?"":"warning"}">${same?"Les contextes documentés concordent.":"Ces parties n’ont pas le même contexte."}<small>${same?"Même classe, zone, difficulté, mode, taille observée et affixes du scénario. L’équipement et les variations de groupe peuvent encore différer.":"Les écarts de difficulté, classe, zone ou groupe influencent les résultats. Comparez les observations sans conclure à une performance équivalente."}</small></div>`+
      `<div class="table-wrap"><table class="detail-table"><thead><tr><th>Mesure</th><th class="num">Partie A</th><th class="num">Partie B</th><th class="num">Écart B − A</th></tr></thead><tbody>${[["Durée","duration"],["Niveau","level"],["Victimes","kills"],["Or","gold"],["Dégâts infligés","damage"],["Soins effectifs","healing"],["Dégâts reçus","taken"]].map(([label,key])=>`<tr><td>${label}</td><td class="num compare-cell">${key==="duration"?clock(a[key]):short(a[key])}</td><td class="num compare-cell">${key==="duration"?clock(b[key]):short(b[key])}</td><td class="num">${((b[key]-a[key])/a[key]*100).toLocaleString("fr-FR",{maximumFractionDigits:1,signDisplay:"always"})} %</td></tr>`).join("")}</tbody></table></div><div class="spacer"></div>${chart(a,S.chartMetric,b)}`;
  }
  function progression() {
    const t=S.progressTab;
    let body="";
    if(t==="records") {
      const list=cohort(),record=k=>(S.resetMetrics.includes(k)||S.resetMetrics.includes("all:"+k)||S.resetMetrics.includes(S.classFilter+":"+k))?null:Math.max(...list.map(r=>r[k]||0)),fmt=(k)=>record(k)==null?"À établir":k==="duration"?clock(record(k)):short(record(k));
      body=`<div class="cohort-strip"><span>Records de <strong>${cohortLabel()}</strong> · toutes difficultés et tous modes confondus</span>${editAction()}</div>${editHint()}<div class="stats-grid">${stat("Survie",fmt("duration"),"Meilleure durée observée",4,false,"duration")}${stat("Dégâts",fmt("damage"),"Meilleur total de partie",2,false,"damage")}${stat("Victimes",fmt("kills"),"Record de partie",5,false,"kills")}${stat("Niveau",fmt("level"),"Plus haut niveau observé",7,false,"level")}</div><div class="panel">${[["Or","gold"],["Soins effectifs","healing"],["Dégâts reçus","taken"]].map(([name,k])=>`<div class="metric-line"><span>${name}</span><strong>${fmt(k)}</strong>${S.edit?btn("Réinitialiser ce record","reset-record",`data-key="${k}"`,"small danger"):btn("Partie source →","open-run",`data-id="${list.reduce((a,b)=>a[k]>b[k]?a:b).id}"`,"small ghost")}</div>`).join("")}</div><div class="callout">Effacer un record ne supprime pas sa partie source.<small>Une nouvelle observation pourra établir un prochain record. L’historique et les autres mesures restent conservés.</small></div>`;
    } else if(t==="classes")body=`<div class="class-grid">${D.classes.map(c=>{const list=D.runs.filter(r=>r.class===c),wins=list.filter(r=>r.result==="victory").length;return `<button class="class-card" data-action="class-history" data-key="${c}">${icon(7)}<h3>${c}</h3><p class="muted">${list.length} parties · ${wins} victoires</p><div class="class-record"><span>Temps suivi</span><strong>${clock(sum(list,"duration"))}</strong></div><div class="class-record"><span>Victimes</span><strong>${short(sum(list,"kills"))}</strong></div><p class="note">Parcourir les parties →</p></button>`;}).join("")}</div>`;
    else if(t==="trends")body=`${tabs([["spells","Sorts"],["items","Accessoires"],["players","Compagnons"]],S.trendKind||"spells","trend-tab")}<div class="cohort-strip"><span>Fréquence dans les builds observés · <strong>${cohortLabel()}</strong></span>${editAction()}</div>${editHint()}${(S.trendKind||"spells")==="spells"?`<div class="table-wrap"><table class="detail-table"><thead><tr><th>Sort</th><th class="num">Parties observées</th><th class="num">Rang maximum</th><th>Favori</th></tr></thead><tbody>${D.spells.filter(s=>!S.hidden.includes("spell:"+s.key)).map(s=>`<tr><td>${icon(s.glyph)}${s.name}</td><td class="num">${s.runs}</td><td class="num">${s.rank}</td><td>${S.edit?btn("…","entry-menu",`data-kind="spell" data-id="${s.key}"`,"small"):heart("spell:"+s.key)}</td></tr>`).join("")}</tbody></table></div>`:S.trendKind==="items"?`<div class="equipment-grid">${D.equipment.slice(3).map(i=>`<div class="item">${icon(i.glyph)}<span><strong>${i.name}</strong><small>Identité regroupée · variantes II / III / IV incluses</small></span>${heart("item:"+i.key)}</div>`).join("")}</div>`:`<div class="panel">${D.party.filter(p=>!p.self).map(p=>`<div class="metric-line"><span>${p.name} · ${p.class}</span><strong>${p.name==="Emp"?3:5} parties observées</strong>${heart("player:"+p.name)}</div>`).join("")}</div>`}<p class="note">Ces mesures décrivent les builds présents et les rangs observés, pas les clics de cartes ni les lancements exacts.</p>`;
    else body=`<div class="two-columns"><div class="panel"><div class="section-heading"><h2>Des objectifs qui vous ressemblent</h2>${btn("Créer un objectif","new-goal","","small primary")}</div>${[["Trois victoires en Heroic III",1,3],["Deux classes victorieuses à Naxxramas",1,2],["Une soirée coop avec vos compagnons",2,3]].map(([name,value,max])=>`<div class="goal">${icon(8)}<div><p>${name}</p><small>Objectif personnel · démonstration</small><div class="progress-track"><span style="width:${value/max*100}%"></span></div></div><strong>${value}/${max}</strong></div>`).join("")}${S.extraGoal?`<div class="goal">${icon(8)}<div><p>${esc(S.extraGoal)}</p><small>Objectif ajouté dans la maquette · progression non connectée au jeu</small></div></div>`:""}</div><div><div class="callout">Votre progression observée, pas un déblocage officiel.<small>Ces objectifs utilisent l’historique disponible. Ils ne prétendent pas connaître votre portefeuille de marques ou vos accès Heroic.</small></div><div class="panel"><h2>Un carnet qui motive</h2><p class="note">Choisir un objectif, retrouver les tentatives associées, puis comparer ses progrès. Les anciennes parties purgées ne sont pas recréées.</p></div></div></div>`;
    return heading("Au fil des aventures","Ma progression","Records, classes et habitudes, sans mélanger les contextes.",scope())+tabs([["records","Records"],["classes","Par classe"],["trends","Tendances"],["goals","Objectifs"]],t,"progress-tab")+body;
  }
  function favorites() {
    const categories=[["runs","Parties"],["spells","Sorts"],["items","Équipement & accessoires"],["players","Compagnons"]],cat=S.favoriteCategory;
    let content="";
    if(cat==="runs") {const list=available().filter(r=>favorite("run:"+r.id));content=list.length?`<div class="run-list">${list.map(row).join("")}</div>`:empty("Vos aventures marquantes, ici","Cliquez sur un cœur dans l’historique pour conserver une partie à portée de main.",btn("Ouvrir l’historique","go","data-route=\"runs\""));}
    else {let entries=[];if(cat==="spells")entries=D.spells.filter(s=>favorite("spell:"+s.key)).map(s=>({key:"spell:"+s.key,name:s.name,detail:`Rang ${s.rank} · ${s.runs} parties observées`,glyph:s.glyph}));else if(cat==="items")entries=D.equipment.filter(i=>favorite("item:"+i.key)).map(i=>({key:"item:"+i.key,name:i.name,detail:i.slot,glyph:i.glyph,item:i.key}));else entries=D.party.filter(p=>favorite("player:"+p.name)).map(p=>({key:"player:"+p.name,name:p.name,detail:p.class,glyph:p.glyph,player:p.name}));content=entries.length?`<div class="run-list">${entries.map(x=>`<div class="favorite-row">${icon(x.glyph)}<div><strong>${x.name}</strong><small>${x.detail}</small></div>${x.item?btn("Consulter","item",`data-key="${x.item}"`,"small"):x.player?btn("Consulter","player",`data-key="${x.player}"`,"small"):btn("Analyser","build-tab","data-tab=\"spells\"","small")}${heart(x.key)}</div>`).join("")}</div>`:empty("Aucun favori dans cette catégorie","Parcourez vos builds et vos compagnons pour ajouter les éléments que vous voulez retrouver.",btn("Explorer mon build","build-tab","data-tab=\"equipment\""));}
    return heading("À retrouver facilement","Mes favoris","Chaque type de souvenir a sa place.")+tabs(categories,cat,"favorite-tab")+content+`<p class="note">Les parties favorites sont protégées de la purge automatique. Une suppression explicite nécessite une confirmation distincte.</p>`;
  }
  function nemesis() {return heading("Comprendre vos défaites","Némésis","Un dernier attaquant n’est pas toujours l’auteur du coup fatal.",editAction())+editHint()+`<div class="stats-grid">${stat("Morts observées",9,"Scénario fictif",5)}${stat("Source confirmée",1,"Message explicite dans le scénario",16)}${stat("Source probable",8,"Dernier attaquant observé",9)}${stat("Source inconnue",0,"Manquant ≠ zéro hors scénario",12)}</div><div class="panel">${D.nemeses.filter(x=>!S.hidden.includes("nemesis:"+x.id)).map(x=>`<div class="favorite-row" data-action="death" data-id="${x.id}" tabindex="0" role="button">${icon(5)}<div><strong>${x.name}</strong><small>${D.zones[x.zone]} · dernière observation ${x.last}</small></div><span>${x.confirmed} confirmé · ${x.probable} probables</span>${S.edit?btn("…","entry-menu",`data-kind="nemesis" data-id="${x.id}"`,"small"):btn("Détails →","death",`data-id="${x.id}"`,"small ghost")}</div>`).join("")}</div><div class="callout">Revoir ce qui a précédé la mort<small>Les derniers impacts conservés et leur ancienneté restent consultables. Aucun score de responsabilité ou coup fatal certain n’est déduit du seul dernier impact.</small></div>`;}
  function appearance() {const names=["Chroniques","Warcraft","Atelier","Essentiel","Grimoire"],colors=["#15232a","#201b12","#232620","#11171a","#e9d9b5"],inks=["#ddbe79","#edcf7d","#d6a57d","#d3dbdf","#694027"];return `<div class="panel"><div class="section-heading"><div><h2>Une aventure, cinq sensibilités</h2><p class="note">Même données et mêmes parcours. Le style vous appartient.</p></div>${tag("Aperçu immédiat","gold")}</div><div class="theme-grid">${THEMES.map((t,i)=>`<button class="theme-option ${S.theme===t?"active":""}" data-action="theme" data-key="${t}" aria-pressed="${S.theme===t}"><div class="theme-swatch" style="--swatch:${colors[i]};--ink:${inks[i]}"><span style="font-family:${i===2||i===3?"AzerothSans":"AzerothSerif"}">Azeroth Stats</span><span class="mini-value">24 aventures</span><span class="mini-block"></span></div><div class="theme-name"><span>${names[i]}</span><span>${S.theme===t?"✓":""}</span></div></button>`).join("")}</div><p class="theme-description">${["Ardoise bleutée, bronze et illustrations : l’identité actuelle, affinée.","Une interprétation Warcraft. Les assets natifs officiels seront référencés dans le client, pas distribués dans cette maquette.","Charbon et cuivre, lignes architecturales, hiérarchie typographique nette.","Contraste calme, densité compacte et décoration réduite à l’essentiel.","Papier chaleureux, encre lisible et esprit de carnet d’aventures."][THEMES.indexOf(S.theme)]}</p></div>`;}
  function settings() {return heading("Votre expérience","Personnaliser","Réglages simples au premier plan. Gestion avancée à part.")+tabs([["appearance","Apparence"],["bar","Ma barre"],["storage","Données"],["versions","V1 ↔ V2"]],S.settingsTab||"appearance","settings-tab")+
    ((S.settingsTab||"appearance")==="appearance"?appearance()+`<div class="spacer"></div><div class="settings-grid"><div class="panel"><h2>Confort de lecture</h2><div class="field"><label for="density">Densité de l’interface</label>${select([["comfort","Confortable"],["compact","Compacte"]],S.density,"density")}</div><p class="note">Le contenu reste accessible dans les deux modes. Les tableaux défilent si la fenêtre est étroite.</p></div><div class="panel"><h2>Retrouver ses repères</h2><p class="note">Thèmes, favoris, filtres et réglages resteront locaux. La V2 conservera les commandes courantes de la V1.</p>${btn("Voir les raccourcis","shortcuts","","ghost")}</div></div>`:S.settingsTab==="bar"?`<div class="panel"><h2>Votre barre, votre essentiel</h2><p class="note">Jusqu’à huit informations, chacune avec sa portée : toutes classes, classe actuelle ou partie actuelle.</p>${hudPreview(S.hud)}${btn("Personnaliser ma barre","hud","","primary")}<p class="note">Le chrono natif du jeu n’est pas dupliqué par défaut.</p></div>`:S.settingsTab==="storage"?`<div class="settings-grid"><div class="panel"><h2>Historique conservé</h2><p class="note">Les totaux restent indépendants des détails conservés. Les favoris sont protégés des purges automatiques.</p><div class="field"><label for="retention">Conserver les détails de</label>${select([["200","200 parties"],["500","500 parties"],["1000","1 000 parties"]],S.retention||"200","retention")}</div>${btn("Gérer mes données…","manage","","ghost")}</div><div class="panel"><h2>Suppression compréhensible</h2><p class="note">Choisissez une partie ou une catégorie, inspectez ce qui sera effacé, puis confirmez. Rien n’est supprimé au premier clic.</p>${btn("Voir un exemple de confirmation","manage","","ghost")}</div></div><div class="callout">La maquette ne contient aucune donnée de jeu.<small>Ses actions ne modifient que les exemples de ce navigateur. La suppression des données partagées dans l’addon aura le même effet après retour à la V1 : les données supprimées ne seront pas ressuscitées.</small></div>`:versionsView());}
  function versionsView() {return `<div class="two-columns"><div class="version-panel"><div class="version-pill">UN PRODUIT, DEUX VERSIONS</div><h2>La V2 prend la relève. Votre histoire continue.</h2><p>La V1 restera téléchargeable, mais deviendra dépréciée et ne recevra plus d’évolutions après la transition.</p><div class="metric-line"><span>V1 → V2</span><strong>Historique et totaux repris</strong></div><div class="metric-line"><span>V2 → V1</span><strong>Nouvelles parties communes conservées</strong></div><div class="metric-line"><span>Détails propres à la V2</span><strong>Invisibles dans la V1</strong></div><p>Le socle commun devra rester lisible par la V1 publiée : mêmes identifiants de parties, mêmes compteurs, mêmes règles d’addition. Les nouveaux détails seront isolés dans une extension que la V1 n’utilise pas.</p>${btn("Simuler le parcours de compatibilité","compatibility","","primary")}</div><div><div class="panel"><h2>Revenir sans repartir de zéro</h2><ol class="help-list"><li>Terminer la partie et quitter le jeu normalement.</li><li>Conserver une sauvegarde des données de l’addon.</li><li>Remettre le paquet V1 compatible puis relancer.</li><li>Retrouver les anciennes parties et les données communes des parties jouées en V2.</li></ol></div><div class="callout">Contrat à valider, pas une migration déjà livrée.<small>Les tests aller-retour sur les versions publiées font partie des critères bloquants avant une release V2. Les deux collecteurs ne fonctionneront pas simultanément.</small></div></div></div>`;}
  function diagnostics() {return heading("Confiance & disponibilité","Comprendre mes données","Voir ce qui est reçu, observé, partiel ou indisponible.",btn("Restaurer les exemples","restore-demo","","ghost")+btn("Copier le diagnostic de démonstration","copy-diagnostic","","ghost"))+`<div class="callout">Vous parcourez une maquette, pas les données du jeu.<small>Aucune API n’est appelée ici. Les états suivants représentent le contrat prévu pour l’addon.</small></div><div class="table-wrap"><table class="detail-table"><thead><tr><th>Fonction</th><th>Disponibilité identifiée</th><th>Ce qu’on peut affirmer</th></tr></thead><tbody>${D.capabilities.map(([name,status,detail])=>`<tr><td>${esc(name)}</td><td>${tag(status,status.includes("Non")?"red":"")}</td><td>${esc(detail)}</td></tr>`).join("")}</tbody></table></div><div class="spacer"></div><div class="panel"><h2>Les mots ont un sens</h2>${line("Résumé officiel","Valeur fournie en fin de partie")}${line("Dernier échantillon","Dernière valeur réellement observée")}${line("Partiel","Une période ou un champ manque")}${line("Indisponible","Aucune donnée vérifiée pour cette mesure")}${line("Probable","Une indication, pas une preuve du coup fatal")}</div>`;}
  function hudValue(block) {const list=block.scope==="run"?[D.runs[0]]:block.scope==="class"?D.runs.filter(r=>r.class==="Guerrier"):D.runs;return block.metric==="runs"?list.length:block.metric==="wins"?list.filter(r=>r.result==="victory").length:block.metric==="time"?clock(sum(list,"duration")):block.metric==="bosses"?"4 obs.":block.metric==="levels"?"Non reçu":short(sum(list,block.metric));}
  function hudPreview(h) {return `<div class="hud-preview">${h.blocks.map(b=>`<div>${h.icons?icon(METRIC_GLYPHS[b.metric]):""}${h.labels?`<small>${METRICS[b.metric]}</small>`:""}<strong>${hudValue(b)}</strong><small>${b.scope==="all"?"Toutes classes":b.scope==="class"?"Guerrier":"Partie actuelle"}</small></div>`).join("")}</div>`;}
  function renderHud() {const h=S.hud;E("hud").innerHTML=h.visible?`<div class="hud-wrap" style="max-width:${h.width}px;min-height:${h.height}px;font-size:${h.font}px"><button class="hud-brand" data-action="go" data-route="home">${icon(1)}<span>Mon aventure</span></button>${h.blocks.map(b=>`<div class="hud-block">${h.icons?icon(METRIC_GLYPHS[b.metric]):""}<span>${h.labels?`<small>${METRICS[b.metric]}</small>`:""}<strong>${hudValue(b)}</strong></span></div>`).join("")}<button class="hud-gear" data-action="hud" aria-label="Personnaliser la barre">⚙</button></div>`:"";}
  function applyTheme() {document.body.dataset.theme=S.theme;document.body.dataset.density=S.density;if(S.density==="compact")document.body.style.setProperty("--row","65px");else document.body.style.removeProperty("--row");}
  function render() {
    applyTheme();renderHud();
    E("navigation").innerHTML=nav.map(([key,label,glyph])=>`<a class="nav-item ${(S.page==="run"&&key==="runs")||(S.page==="compare"&&key==="runs")||S.page===key?"active":""}" href="#${key}" title="${label}">${icon(glyph)}<span>${label}</span>${key==="favorites"?`<span class="nav-count">${S.favorites.length}</span>`:""}</a>`).join("");
    const current=nav.find(v=>v[0]===S.page)?.[1]||({run:"Mes parties / Bilan",compare:"Mes parties / Comparer",settings:"Personnaliser",diagnostics:"Données & diagnostic"}[S.page]);
    E("breadcrumb").innerHTML=`Votre espace <span class="muted"> / </span> <strong>${esc(current)}</strong>`;
    const views={home,runs,run:analysis,analyze:analysis,compare,progress:progression,favorites,nemesis,settings,diagnostics};
    E("content").innerHTML=views[S.page]();
  }
  function go(page,tab="") {if(!["home","runs","run","analyze","compare","progress","favorites","nemesis","settings","diagnostics"].includes(page))page="home";S.page=page;S.tab=tab;S.edit=false;const hash=page==="run"?`run/${S.selected}/${tab||"overview"}`:page==="analyze"?`analyze/${tab||"overview"}`:page;history.replaceState(null,"","#"+hash);render();E("content").scrollTop=0;}
  function toast(message) {clearTimeout(S.toastTimer);E("toast").textContent=message;E("toast").hidden=false;S.toastTimer=setTimeout(()=>E("toast").hidden=true,4000);}
  let previousFocus=null;
  function modal(title,description,body,footer="",compact=false) {if(E("overlay").hidden)previousFocus=document.activeElement;E("overlay").hidden=false;E("overlay").innerHTML=`<section class="dialog ${compact?"compact":""}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="dialog-header"><div><h2 id="dialog-title">${title}</h2><p>${description}</p></div><button class="icon-btn" data-action="close" aria-label="Fermer">×</button></div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-footer">${footer}</div>`:""}</section>`;document.body.style.overflow="hidden";queueMicrotask(()=>E("overlay").querySelector("input,button,select")?.focus());}
  function close() {E("overlay").hidden=true;E("overlay").innerHTML="";document.body.style.overflow="";S.overlay=null;S.hudDraft=null;if(previousFocus?.isConnected)previousFocus.focus();}
  function quality() {modal("Des chiffres qu’on peut comprendre","La provenance est visible, sans envahir l’interface.",`<div class="callout">Toutes les données de cette maquette sont fictives.<small>Les badges illustrent la future UX. Ils ne certifient pas une fonction déjà développée ou validée en jeu.</small></div>${[["Résumé officiel","Un compteur transmis à la fin de la partie."],["Observé","Une valeur effectivement présente dans un relevé."],["Échantillonné","Des relevés espacés : les intervalles ne sont pas connus en continu."],["Partiel","Un début manquant, un compteur absent ou un changement non observé."],["Indisponible","On n’affiche ni zéro inventé ni estimation déguisée."]].map(([a,b])=>`<div class="metric-line"><strong>${a}</strong><span>${b}</span></div>`).join("")}`,btn("Tout le diagnostic","go","data-route=\"diagnostics\"","primary"),true);}
  function hudDialog() {
    if(!S.hudDraft)S.hudDraft=JSON.parse(JSON.stringify(S.hud));const h=S.hudDraft;
    modal("Ma barre","Un brouillon indépendant : Appliquer enregistre, Annuler conserve votre barre.",`${hudPreview(h)}<div class="section-heading"><h2>Choisir mes informations</h2><small>${h.blocks.length} / 8 blocs</small></div>${h.blocks.map((b,i)=>`<div class="hud-editor-row">${select(Object.entries(METRICS),b.metric,`hud-metric-${i}`,`data-hud-index="${i}" data-hud-field="metric" aria-label="Information ${i+1}"`)}${select([["all","Toutes les classes"],["class","Classe actuelle"],["run","Partie actuelle"]],b.scope,`hud-scope-${i}`,`data-hud-index="${i}" data-hud-field="scope" aria-label="Portée ${i+1}"`)}${btn("↑","hud-move",`data-index="${i}" data-delta="-1" aria-label="Monter le bloc ${i+1}" ${i===0?"disabled":""}`,"small")}${btn("↓","hud-move",`data-index="${i}" data-delta="1" aria-label="Descendre le bloc ${i+1}" ${i===h.blocks.length-1?"disabled":""}`,"small")}${btn("×","hud-remove",`data-index="${i}" aria-label="Retirer le bloc ${i+1}" ${h.blocks.length===1?"disabled":""}`,"small")}</div>`).join("")}${btn("+ Ajouter une information","hud-add",h.blocks.length>=8?"disabled":"","small ghost")}<div class="subtle-divider"></div><h2>Confort et dimensions</h2><div class="settings-grid">${[["width","Largeur",480,1260,10,"px"],["height","Hauteur",38,76,2,"px"],["font","Texte",10,16,1,"px"]].map(([key,label,min,max,step,unit])=>`<div class="field"><div class="field-meta"><label for="hud-${key}">${label}</label><output id="hud-${key}-output">${h[key]} ${unit}</output></div><input id="hud-${key}" data-hud-setting="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${h[key]}"></div>`).join("")}<div><label class="check-line">Afficher les icônes <input type="checkbox" data-hud-check="icons" ${h.icons?"checked":""}></label><label class="check-line">Afficher les libellés <input type="checkbox" data-hud-check="labels" ${h.labels?"checked":""}></label></div></div><p class="note">La barre du haut est inchangée tant que vous n’avez pas appliqué. Le compteur de boss reste « observé », les niveaux stockés restent indisponibles s’ils n’ont pas été reçus.</p>`, `<span class="left">Préférences locales à la maquette</span>${btn("Annuler","close")}${btn("Appliquer à ma barre","hud-apply","","primary")}`);
  }
  let manage={kind:"run",id:"d11",stage:1};
  function manageDialog() {
    let r=D.runs.find(x=>x.id===manage.id)||D.runs[1];
    const names={run:"Une partie",history:"Historique",records:"Records",nemesis:"Némésis",trends:"Tendances",favorites:"Favoris"};
    const removed=manage.kind==="run"?`Détails de ${D.zones[r.zone]} · ${r.date}`:manage.kind==="history"?`${available().filter(x=>!favorite("run:"+x.id)&&x.result!=="live").length} parties non favorites terminées`:names[manage.kind];
    const preview=`<aside class="manage-preview"><div class="eyebrow">${manage.kind==="run"?"LA PARTIE CONCERNÉE":"LE PÉRIMÈTRE"}</div>${manage.kind==="run"?photo(r):icon(manage.kind==="nemesis"?5:9)}<h3>${manage.kind==="run"?D.zones[r.zone]:names[manage.kind]}</h3><p class="note">${manage.kind==="run"?`${r.date} · ${r.class} · ${diff(r)} · ${r.mode}`:"Toutes les classes · données de démonstration"}</p>${manage.kind==="run"?line("Résultat",result(r))+line("Durée",clock(r.duration))+line("Niveau",r.level)+line("Victimes",n(r.kills))+line("Dégâts",short(r.damage)):""}</aside>`;
    modal(manage.stage===1?"Choisir ce que je veux effacer":"Vérifier avant de supprimer",manage.stage===1?"1 · Sélection. Aucune donnée n’est supprimée à cette étape.":"2 · Confirmation explicite. Les autres catégories restent conservées.",`<div class="manage-layout"><div>${manage.stage===1?tabs(Object.entries(names),manage.kind,"manage-kind"):""}${manage.kind==="run"?`<div class="run-list">${available().filter(x=>x.result!=="live").slice(0,5).map(x=>`<button class="manage-run ${manage.id===x.id?"active":""}" data-action="manage-run" data-id="${x.id}" ${manage.stage===2?"disabled":""}><span><strong>${D.zones[x.zone]} · ${result(x)} · ${clock(x.duration)}</strong><small>${x.date} · ${x.class} · ${diff(x)} · ${x.mode}</small></span>${favorite("run:"+x.id)?"♥":""}</button>`).join("")}</div>`:`<div class="panel"><h2>${names[manage.kind]}</h2><p class="note">Vous effacerez uniquement cette catégorie ${manage.kind==="history"?"de détails. Les favoris et la partie en cours sont protégés":"dans le scénario de démonstration"}.</p></div>`}<div class="callout warning"><strong>Sera supprimé :</strong> ${esc(removed)}<small>La maquette applique cette action à ses exemples uniquement.</small></div><div class="callout"><strong>Sera conservé :</strong> ${manage.kind==="run"||manage.kind==="history"?"totaux, records, autres catégories et réglages":"historique de combat, builds, autres catégories et réglages"}.<small>Une suppression dans les futures données communes concernera aussi ce qui restera visible après retour en V1.</small></div>${manage.kind==="run"&&favorite("run:"+r.id)?`<div class="callout warning">Cette partie est favorite. Sa suppression explicite retirera aussi son favori.</div>`:""}</div>${preview}</div>`,`${btn("Annuler","close")}${manage.stage===2?btn("← Modifier la sélection","manage-back"):""}${manage.stage===1?btn("Vérifier la suppression →","manage-next","","primary"):btn("Supprimer ces données de démonstration","manage-confirm","","danger")}`);
  }
  function entryMenu(kind,id) {const labels={run:"cette partie",source:"cette source",spell:"ce sort",nemesis:"cet adversaire"};modal("Modifier uniquement cet élément",`Vous avez sélectionné ${labels[kind]||"cet élément"}.`,`<p>Une action ciblée ne réinitialise pas toute la catégorie.</p><div class="spacer"></div>${kind==="run"?btn("Voir la partie avant de décider","open-run",`data-id="${esc(id)}"`,"ghost")+`<div class="spacer"></div>`+btn("Choisir cette partie pour suppression…","manage-one",`data-id="${esc(id)}"`,"danger"):btn("Masquer cette ligne dans la maquette","hide-entry",`data-kind="${kind}" data-id="${esc(id)}"`,"ghost")}<p class="note">Masquer change seulement la présentation ; les totaux restent inchangés. Les remises à zéro ciblées de données communes devront être compatibles avec le retour en V1.</p>`,btn("Fermer","close"),true);}
  function openItem(key) {const item=equipmentFor(run()).find(i=>i.key===key);if(!item)return;modal(item.name,"Description de démonstration · parcours du tooltip historique",`<div class="item-tooltip"><h3>${item.name}</h3><small>${item.slot}</small>${item.lines.map(t=>`<p>${esc(t)}</p>`).join("")}<div class="subtle-divider"></div><small>${item.source||"Données fictives. Dans l’addon : description native capturée avec cette partie."}</small></div><p class="note">La V2 n’inventera pas le nombre d’étoiles ou l’activation d’un set. Les variantes d’accessoires sont regroupées sans perdre leur description enregistrée.</p>`,`${heart("item:"+item.key)}${btn("Fermer","close")}`,true);}
  function drawer(title,subtitle,body) {if(E("overlay").hidden)previousFocus=document.activeElement;S.overlay="drawer";E("overlay").hidden=false;E("overlay").innerHTML=`<section class="drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title"><button class="icon-btn drawer-close" data-action="close" aria-label="Fermer">×</button><div class="eyebrow">Détail de l’observation</div><h2 id="drawer-title">${esc(title)}</h2><p>${esc(subtitle)}</p>${body}</section>`;document.body.style.overflow="hidden";queueMicrotask(()=>E("overlay").querySelector("button")?.focus());}
  function compatibility() {modal("V1 → V2 → V1 → V2","Simulation du contrat de compatibilité. Aucun vrai fichier n’est chargé.",`<div class="timeline"><div class="timeline-item"><span class="timeline-time">V1</span><p>12 parties et leurs totaux communs</p><small>Le schéma historique reste lisible ; IDs et compteurs déjà comptabilisés sont conservés.</small></div><div class="timeline-item"><span class="timeline-time">V2</span><p>Deux nouvelles parties et des analyses enrichies</p><small>14 parties dans le socle partagé. Les rencontres, affixes et nouvelles analyses restent dans une extension V2 séparée.</small></div><div class="timeline-item"><span class="timeline-time">V1</span><p>Les 14 parties restent visibles</p><small>La V1 reprend leurs statistiques communes. Elle ignore les champs d’analyse V2, sans avoir besoin de les afficher.</small></div><div class="timeline-item"><span class="timeline-time">V2</span><p>Les analyses enrichies sont retrouvées</p><small>Objectif du format extensible : conserver les détails V2 pendant un aller-retour normal, dans la limite des suppressions explicites.</small></div></div><div class="callout warning">À prouver avant publication<small>Tests sur les versions V1 publiées, sérialisation réelle SavedVariables, jeu fermé/rechargé, purge et réinitialisation, pas uniquement ce scénario visuel.</small></div>`,btn("Compris","close","","primary"));}
  function searchDialog(query="") {modal("Retrouver une aventure","Recherchez une zone, une classe ou une date.",`<input id="global-search" type="search" placeholder="Ex. Naxxramas, Mage, 29 oct…" value="${esc(query)}" style="width:100%" aria-label="Recherche globale"><div id="global-results" class="run-list" style="margin-top:15px">${available().filter(r=>`${D.zones[r.zone]} ${r.class} ${r.date}`.toLowerCase().includes(query.toLowerCase())).slice(0,5).map(row).join("")||"<p class=\"note\" style=\"padding:18px\">Aucun résultat dans les données de démonstration.</p>"}</div>`,btn("Fermer","close"),false);queueMicrotask(()=>{const e=E("global-search");e?.focus();e?.setSelectionRange(query.length,query.length);});}
  function eventAction(action,el) {
    const d=el.dataset;
    switch(action) {
      case "go":close();go(d.route);break;
      case "open-run":close();S.selected=d.id;go("run",d.sub||"overview");break;
      case "tab":S.tab=d.tab;render();break;
      case "analyze-tab":S.tab=d.tab;go("analyze",d.tab);break;
      case "combat-tab":S.combatTab=d.tab;render();break;
      case "build-tab":S.buildTab=d.tab;if(!["run","analyze"].includes(S.page))go("analyze","build");else{S.tab="build";render();}break;
      case "progress-tab":S.progressTab=d.tab;if(S.page!=="progress")go("progress");else render();break;
      case "settings-tab":S.settingsTab=d.tab;render();break;
      case "favorite-tab":S.favoriteCategory=d.tab;render();break;
      case "trend-tab":S.trendKind=d.tab;render();break;
      case "chart":S.chartMetric=d.key;render();break;
      case "page":S.pageIndex+=Number(d.delta);render();break;
      case "edit":S.edit=!S.edit;render();break;
      case "restore-hidden":S.hidden=[];persist();render();toast("Les lignes masquées sont réaffichées.");break;
      case "favorite":{const key=d.key;S.favorites=favorite(key)?S.favorites.filter(x=>x!==key):[...S.favorites,key].slice(-100);persist();if(E("overlay").hidden)render();else {el.classList.toggle("saved",favorite(key));el.textContent=favorite(key)?"♥":"♡";el.setAttribute("aria-pressed",String(favorite(key)));}toast(favorite(key)?"Ajouté à vos favoris de démonstration.":"Retiré des favoris. La partie reste conservée.");break;}
      case "reset-filters":S.classFilter="all";S.difficulty="all";S.mode="all";S.result="all";S.query="";S.pageIndex=1;render();break;
      case "compare-from":S.compareA=d.id;go("compare");break;
      case "class-history":S.classFilter=d.key;go("runs");break;
      case "theme":S.theme=d.key;persist();render();toast("Thème appliqué à la maquette : "+d.key+".");break;
      case "close":close();break;
      case "quality":quality();break;
      case "search":searchDialog();break;
      case "versions":S.settingsTab="versions";go("settings");break;
      case "compatibility":compatibility();break;
      case "hud":S.hudDraft=null;hudDialog();break;
      case "hud-add":if(S.hudDraft.blocks.length<8)S.hudDraft.blocks.push({metric:"gold",scope:"run"});hudDialog();break;
      case "hud-remove":if(S.hudDraft.blocks.length>1)S.hudDraft.blocks.splice(Number(d.index),1);hudDialog();break;
      case "hud-move":{const i=Number(d.index),j=i+Number(d.delta),arr=S.hudDraft.blocks;if(j>=0&&j<arr.length)[arr[i],arr[j]]=[arr[j],arr[i]];hudDialog();break;}
      case "hud-apply":S.hud=JSON.parse(JSON.stringify(S.hudDraft));persist();close();render();toast("Votre barre est enregistrée. Les données du jeu n’ont pas été touchées.");break;
      case "item":openItem(d.key);break;
      case "entry-menu":entryMenu(d.kind,d.id);break;
      case "hide-entry":{const key=d.kind+":"+d.id;if(!S.hidden.includes(key))S.hidden.push(key);persist();close();render();toast("Ligne masquée. Les totaux sont conservés.");break;}
      case "manage":manage={kind:"run",id:available().find(r=>r.result!=="live")?.id||"d11",stage:1};manageDialog();break;
      case "manage-one":manage={kind:"run",id:d.id,stage:1};manageDialog();break;
      case "manage-kind":manage.kind=d.tab;manage.stage=1;manageDialog();break;
      case "manage-run":manage.id=d.id;manageDialog();break;
      case "manage-next":manage.stage=2;manageDialog();break;
      case "manage-back":manage.stage=1;manageDialog();break;
      case "manage-confirm":if(manage.stage!==2)return;if(manage.kind==="run"){if(!S.deleted.includes(manage.id))S.deleted.push(manage.id);S.favorites=S.favorites.filter(k=>k!=="run:"+manage.id);}else if(manage.kind==="history"){S.deleted=[...new Set([...S.deleted,...available().filter(r=>r.result!=="live"&&!favorite("run:"+r.id)).map(r=>r.id)])];}else if(manage.kind==="favorites")S.favorites=[];else if(manage.kind==="records")S.resetMetrics=["duration","damage","gold","kills","level","healing","taken"];else if(manage.kind==="nemesis")S.hidden.push(...D.nemeses.map(x=>"nemesis:"+x.id));else if(manage.kind==="trends")S.hidden.push(...D.spells.map(x=>"spell:"+x.key));persist();close();render();toast("Données de démonstration supprimées. Les autres catégories sont conservées.");break;
      case "reset-record":modal("Réinitialiser seulement ce record ?",`Mesure : ${{duration:"Survie",damage:"Dégâts",gold:"Or",kills:"Victimes",level:"Niveau",healing:"Soins",taken:"Dégâts reçus"}[d.key]} · ${cohortLabel()}`,`<p>Ce record sera remis à l’état « À établir » dans la maquette.</p><div class="callout"><strong>Conservés :</strong> parties sources, autres records, totaux, builds et réglages.</div><p class="note">Dans l’addon, la portée choisie et les masques de remise à zéro devront être respectés aussi après retour en V1.</p>`,`${btn("Annuler","close")}${btn("Réinitialiser ce record","confirm-record",`data-key="${d.key}"`,"danger")}`,true);break;
      case "confirm-record":if(!S.resetMetrics.includes(S.classFilter+":"+d.key))S.resetMetrics.push(S.classFilter+":"+d.key);persist();close();render();toast("Ce record uniquement a été réinitialisé dans le scénario.");break;
      case "attribute":{const a=D.attributes.find(x=>x[3]===d.key);modal(a[0],"Lire une caractéristique sans confondre ses sources.",`<div class="panel">${line("Total observé",a[1])}${line("Équipement déclaré",a[2]||"Non exposé")}</div><p class="note">Le total peut combiner niveau, talents, équipement, accessoires et effets temporaires. Une soustraction ne permet pas d’attribuer précisément le reste à une carte. Les unités des contributions natives seront traitées champ par champ.</p>`,btn("Compris","close","","primary"),true);break;}
      case "player":{const p=partyFor(run()).find(x=>x.name===d.key);drawer(p.name,p.class+" · relevé commun de démonstration",`<div class="spacer"></div>${line("Dégâts",short(p.damage))}${line("Moyenne de partie",short(p.dps)+" /s")}${line("Meilleure source",p.top)}${line("Soutien observé",p.support)}<div class="callout">Ce que le jeu ne fournit pas<small>Soins, dégâts reçus et équipement complets de cet allié : non exposés dans le relevé de groupe vérifié.</small></div>${heart("player:"+p.name)}`);break;}
      case "coop-support":modal("Le soutien, avec le bon niveau de certitude","Événements locaux observés, pas un classement de soigneurs.",`<div class="panel">${D.party.map(p=>line(p.name,p.support)).join("")}</div><div class="callout">Une barre de réanimation interrompue ne suffit pas.<small>Seule une transition cohérente permettrait de qualifier une reprise du combat. À valider sur les paquets natifs en développement.</small></div>`,btn("Fermer","close"),true);break;
      case "encounter":{const b=encountersFor(run()).find(x=>x.id===d.id);drawer(b.name,b.state,`<div class="spacer"></div>${line("Apparition observée",clock(b.t))}${line("Fenêtre observée",b.end?clock(b.end-b.t):"Toujours ouverte")}${line("Dégâts du relevé",short(b.damage))}<div class="callout">Aucune victoire déduite d’une disparition.<small>Les frontières, boss simultanés et compteurs périmés seront validés avant d’archiver un bilan de rencontre.</small></div><div class="spacer"></div><h2>Sources de dégâts · scénario</h2>${spellsFor(run()).slice(0,3).map(s=>line(s.name,short(b.damage*s.share/100))).join("")}`);break;}
      case "death":{const x=D.nemeses.find(y=>y.id===d.id);drawer(x.name,"Historique de mort · scénario de démonstration",`${photo({zone:x.zone},"cover")}${line("Source confirmée",x.confirmed)}${line("Source probable",x.probable)}<div class="spacer"></div><h2>Les derniers impacts observés</h2>${[["−1,8 s",146],["−1,2 s",203],["−0,4 s",189]].map(([age,amount])=>line(x.name+" · "+age,amount+" dégâts")).join("")}<div class="callout">Dernier attaquant : probable<small>Ces impacts ne prouvent pas à eux seuls le coup fatal. Les données fictives illustrent la distinction confirmé / probable déjà présente en V1.</small></div>`);break;}
      case "new-goal":modal("Un objectif personnel","Créez un repère, pas un déblocage officiel du jeu.",`<label for="goal-name">Votre objectif</label><input id="goal-name" maxlength="100" value="Gagner trois parties avec mon Guerrier" style="width:100%;margin-top:10px"><p class="note">La maquette mémorise le titre pendant cette visite. Le suivi réel est une future fonction.</p>`,`${btn("Annuler","close")}${btn("Ajouter cet objectif","save-goal","","primary")}`,true);break;
      case "save-goal":S.extraGoal=E("goal-name").value.slice(0,100).trim()||"Mon prochain défi";close();render();toast("Objectif de démonstration ajouté.");break;
      case "shortcuts":modal("Retrouver les raccourcis familiers","Commandes prévues dans l’addon, non exécutées par cette maquette.",`<div class="panel">${line("/azstats","Ouvrir / fermer")}${line("/azstats history","Mes parties")}${line("/azstats compare","Comparer")}${line("/azstats hud","Ma barre")}${line("/azstats diagnose","Diagnostic")}</div><p class="note">Dans cette maquette : / ouvre la recherche, Échap ferme les fenêtres.</p>`,btn("Fermer","close"),true);break;
      case "restore-demo":modal("Restaurer le scénario de démonstration ?","Aucune donnée du jeu ne sera concernée.","<p>Les favoris, notes, suppressions, records et réglages de cette maquette seront remis à leur état initial. Vos vraies sauvegardes ne sont jamais lues par cette page.</p>",btn("Annuler","close")+btn("Restaurer les exemples","confirm-restore","","primary"),true);break;
      case "confirm-restore":try{localStorage.removeItem(KEY);}catch{}location.href=location.pathname+"#home";location.reload();break;
      case "copy-diagnostic":{const text="Azeroth Stats V2 — prototype offline\nDonnées synthétiques, aucun accès au jeu\nThème : "+S.theme+"\nPortée : "+cohortLabel();if(navigator.clipboard?.writeText)navigator.clipboard.writeText(text).then(()=>toast("Diagnostic de démonstration copié.")).catch(()=>modal("Diagnostic de démonstration","Copiez ce texte si votre navigateur interdit le presse-papiers.",`<textarea readonly rows="5">${esc(text)}</textarea>`,btn("Fermer","close"),true));else modal("Diagnostic de démonstration","Texte à copier manuellement.",`<textarea readonly rows="5">${esc(text)}</textarea>`,btn("Fermer","close"),true);break;}
      case "toast":toast(d.message);break;
      case "tour":modal("Le parcours à essayer","Quatre étapes pour juger la V2 avec de vraies interactions.",`<ol class="help-list"><li><strong>Mes parties :</strong> filtrez par classe / coop, ouvrez un bilan, ajoutez un cœur et une note.</li><li><strong>Analyser :</strong> parcourez Combat, Build, Journal, Rencontres et Coop ; ouvrez une description d’équipement.</li><li><strong>Ma progression :</strong> comparez deux parties, éditez un record ciblé et retrouvez vos favoris par catégorie.</li><li><strong>Personnaliser :</strong> essayez les cinq thèmes et Ma barre ; testez Annuler puis Appliquer.</li></ol><div class="callout">V2 remplace V1, sans couper votre historique.<small>Le contrat prévu est aller-retour : données communes conservées dans les deux sens, détails V2 ignorés par V1. La compatibilité réelle sera testée avant publication.</small></div>`,`${btn("Le contrat V1 ↔ V2","versions")}${btn("Commencer la visite","close","","primary")}`);break;
    }
  }
  document.addEventListener("click",e=>{const el=e.target.closest("[data-action]");if(el&&!el.disabled){e.preventDefault();e.stopPropagation();eventAction(el.dataset.action,el);}else if(e.target===E("overlay"))close();});
  document.addEventListener("change",e=>{
    const el=e.target,id=el.id;
    if(el.dataset.hudIndex!=null&&S.hudDraft){S.hudDraft.blocks[Number(el.dataset.hudIndex)][el.dataset.hudField]=el.value;hudDialog();return;}
    if(el.dataset.hudCheck&&S.hudDraft){S.hudDraft[el.dataset.hudCheck]=el.checked;hudDialog();return;}
    const filters={"class-filter":"classFilter","difficulty-filter":"difficulty","mode-filter":"mode","result-filter":"result"};
    if(filters[id]){S[filters[id]]=el.value;S.pageIndex=1;render();return;}
    if(id==="run-picker"){S.selected=el.value;render();}
    else if(id==="compare-a"){S.compareA=el.value;render();}
    else if(id==="compare-b"){S.compareB=el.value;render();}
    else if(id==="attribute-group"){S.attributeGroup=el.value;render();}
    else if(id==="journal-kind"){S.journalKind=el.value;render();}
    else if(id==="density"){S.density=el.value;persist();render();}
    else if(id==="retention"){S.retention=el.value;toast("Préférence illustrée : "+el.value+" parties. Aucune purge de données de jeu.");}
  });
  let searchTimer;
  document.addEventListener("input",e=>{
    const el=e.target;
    if(el.id==="history-search"){const pos=el.selectionStart;S.query=el.value;S.pageIndex=1;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{render();const input=E("history-search");input?.focus();input?.setSelectionRange(pos,pos);},160);}
    else if(el.id==="global-search"){const query=el.value;E("global-results").innerHTML=available().filter(r=>`${D.zones[r.zone]} ${r.class} ${r.date}`.toLowerCase().includes(query.toLowerCase())).slice(0,5).map(row).join("")||'<p class="note" style="padding:18px">Aucun résultat dans la démonstration.</p>';}
    else if(el.id==="run-note"){S.notes[run().id]=el.value.slice(0,240);persist();}
    else if(el.dataset.hudSetting&&S.hudDraft){const k=el.dataset.hudSetting;S.hudDraft[k]=Number(el.value);E("hud-"+k+"-output").textContent=el.value+" px";}
  });
  document.addEventListener("keydown",e=>{
    if(e.key==="Escape"&&!E("overlay").hidden){close();return;}
    if(e.key==="/"&&!["INPUT","TEXTAREA","SELECT"].includes(e.target.tagName)){e.preventDefault();searchDialog();}
    if((e.key==="Enter"||e.key===" ")&&e.target.matches('[role="button"][data-action]')){e.preventDefault();eventAction(e.target.dataset.action,e.target);}
    if(e.key==="Tab"&&!E("overlay").hidden){const nodes=[...E("overlay").querySelectorAll('button:not(:disabled),input,textarea,select,[tabindex="0"]')].filter(x=>x.offsetParent!==null);if(nodes.length){const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}
  });
  function readHash(){const [page,id,tab]=location.hash.slice(1).split("/");if(page==="run"&&D.runs.some(r=>r.id===id)){S.selected=id;S.tab=analysisTabs.some(t=>t[0]===tab)?tab:"overview";}else if(page==="analyze")S.tab=analysisTabs.some(t=>t[0]===id)?id:"overview";S.page=[...nav.map(n=>n[0]),"run","compare","settings","diagnostics"].includes(page)?page:"home";render();}
  window.addEventListener("hashchange",()=>{close();readHash();});
  readHash();
  // A read-only inspection hook aids prototype smoke tests; no production API.
  window.AZS_PROTOTYPE = Object.freeze({inspect:()=>JSON.parse(JSON.stringify({page:S.page,theme:S.theme,favorites:S.favorites,selected:S.selected,hud:S.hud,deleted:S.deleted,version:D.version}))});
})();
